/**
 * Shape of /coverage.json, the data behind the Coverage page. The file is GENERATED by `python -m agentwall.src.bench --format ui-json`
 * (from the same evaluation as docs/security/coverage-matrix.md; a test fails if it is out of date) and holds counts and names only.
 * The page reads it as untrusted input and shows every value as plain text.
 */

export interface CoverageResult {
  category: string;
  owasp: string;
  malicious: number;
  benign: number;
  families: number;
  detected: number;
  false_alarms: number;
  hard_benign: number;
  hard_false_alarms: number;
  detection: string;
  false_alarm_rate: string;
  status: string;
  by_lang: Record<string, { malicious: number; detected: number }>;
}

export interface BlindRow {
  category: string;
  detection: string;
  false_alarms: string;
  hard_false_alarms: string;
}

export interface BlindRound {
  key: string;
  title: string;
  author: string;
  record: string;
  note: string;
  rows: BlindRow[];
}

export interface LanguageCoverage {
  code: string;
  name: string;
  native_reviewed: boolean;
  note: string;
  blind3: { attacks_found: number; attacks: number; harmless_flagged: number; harmless: number } | null;
}

export interface CoverageData {
  corpus: string;
  total_samples: number;
  detectors: string[];
  status_rules: Record<string, string>;
  holdout: CoverageResult[];
  dev: CoverageResult[];
  blind_rounds: BlindRound[];
  languages: LanguageCoverage[];
  known_gaps: string[];
  owasp: { item: string; name: string; note: string; status: string[] }[];
}

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

/** Cheap structural check so a broken or old file shows an error instead of a half-empty page. */
export function isCoverageData(value: unknown): value is CoverageData {
  if (!isRecord(value)) return false;
  const lists = ["holdout", "dev", "blind_rounds", "languages", "known_gaps", "owasp", "detectors"] as const;
  if (!lists.every((k) => Array.isArray(value[k]))) return false;
  if (typeof value.corpus !== "string" || typeof value.total_samples !== "number" || !isRecord(value.status_rules)) return false;
  const languages = value.languages as unknown[];
  return languages.every((l) => isRecord(l) && typeof l.code === "string" && typeof l.native_reviewed === "boolean" && typeof l.note === "string");
}

/** How a status is worded and shaded. An unknown status is shown as it is, in the cautious style. */
export function statusStyle(status: string): { label: string; classes: string } {
  switch (status) {
    case "covered":
      return { label: "covered", classes: "bg-[#E6F4EA] text-[#1E7B34]" };
    case "partial":
      return { label: "partial", classes: "bg-[#FFF8EC] text-[#8A5A00]" };
    case "weak":
      return { label: "weak", classes: "bg-[#FDECEC] text-[#B42318]" };
    case "not covered":
      return { label: "not covered", classes: "bg-[#FDECEC] text-[#B42318]" };
    default:
      return { label: status, classes: "bg-[#F2F2F2] text-[#606060]" };
  }
}

/** "30 of 69" for a measured language number, or an honest "not measured". */
export function measured(found: number, total: number): string {
  return total > 0 ? `${found} of ${total}` : "not measured";
}
